export default InstanceCullingNode;
/**
 * TSL function for creating an instance culling node that applies GPU-culled
 * instance transforms to vertex positions and normals.
 *
 * This is the main entry point for enabling GPU culling in your material. The node
 * automatically handles the indirection from draw index to original instance ID.
 *
 * **Example: Basic GPU frustum culling**
 *
 * ```js
 * import { ComputeInstanceCulling } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * // Create instanced mesh with 100,000 instances
 * const geometry = new THREE.BoxGeometry(1, 1, 1);
 * const material = new THREE.MeshStandardNodeMaterial();
 * const mesh = new THREE.InstancedMesh(geometry, material, 100000);
 *
 * // Scatter instances randomly
 * const matrix = new THREE.Matrix4();
 * for (let i = 0; i < 100000; i++) {
 *   matrix.makeTranslation(
 *     (Math.random() - 0.5) * 1000,
 *     (Math.random() - 0.5) * 100,
 *     (Math.random() - 0.5) * 1000
 *   );
 *   mesh.setMatrixAt(i, matrix);
 * }
 *
 * // Create GPU culler
 * const culler = new ComputeInstanceCulling(mesh, renderer);
 *
 * // Culling patch is applied automatically to material.setupPosition()
 * // so you can keep using positionNode normally.
 *
 * scene.add(mesh);
 * ```
 *
 * @function instanceCulling
 * @short TSL node that applies ComputeInstanceCulling transforms to vertex positions and normals for culled instances.
 * @category TSL
 * @tags WebGPU
 * @tsl
 * @param {ComputeInstanceCulling} culler - The GPU instance culler.
 * @returns {InstanceCullingNode} Node that applies culled instance transforms.
 */
export const instanceCulling: any;
export function instanceCullingIndex(culler: ComputeInstanceCulling): Node<uint>;
export function instanceCullingMatrix(culler: ComputeInstanceCulling, idNode?: Node<int>): Node<mat4>;
/**
 * TSL Node that applies GPU-culled instance matrix transformations to geometry.
 * Works like Three.js's instancedMesh() node but uses culled instance IDs.
 *
 * This node is used internally by {@link ComputeInstanceCulling} and typically
 * does not need to be instantiated directly. Use {@link instanceCulling} instead.
 *
 * @class InstanceCullingNode
 * @extends Node
 * @private
 */
declare class InstanceCullingNode {
    static get type(): string;
    /**
     * Constructs a new instance culling node.
     *
     * @param {ComputeInstanceCulling} culler - The GPU instance culler.
     */
    constructor(culler: ComputeInstanceCulling);
    /**
     * The GPU instance culler that provides culled instance IDs and instance matrices.
     *
     * @type {ComputeInstanceCulling}
     */
    culler: ComputeInstanceCulling;
    /**
     * Setups the node and assigns transformed vertex data to positionLocal and normalLocal.
     *
     * @param {NodeBuilder} builder - The current node builder.
     */
    setup(builder: NodeBuilder): void;
}
